const record = $input.first()?.json || {};
const request = $('Normalize Redeem Request').first().json;

function field(name, fallback = '') {
  return record[name] ?? record.fields?.[name] ?? fallback;
}

const now = new Date();
const expiresAtRaw = field('Expires At');
const expiresAt = expiresAtRaw ? new Date(expiresAtRaw) : null;
const status = String(field('Status', 'Active') || 'Active');
const redeemAttempts = Number(field('Redeem Attempts', 0) || 0);

const parts = new Intl.DateTimeFormat('en-GB', {
  timeZone: 'Europe/Rome',
  weekday: 'short',
  hour: '2-digit',
  minute: '2-digit',
  hour12: false,
}).formatToParts(now);
const weekday = parts.find((part) => part.type === 'weekday')?.value || '';
const hour = Number(parts.find((part) => part.type === 'hour')?.value || 0);
const minute = Number(parts.find((part) => part.type === 'minute')?.value || 0);
const minutesNow = hour * 60 + minute;
const isPromoDay = ['Mon', 'Tue', 'Wed', 'Thu'].includes(weekday);
const isPromoHour = minutesNow >= (18 * 60 + 30) && minutesNow <= (22 * 60 + 30);
const allowOutsidePromoForTest = false;
const storedToken = String(field('Redeem Token', '') || '');
const tokenMatches = storedToken.length > 0 && storedToken === request.token;
const isRedeemed = status.toLowerCase() === 'redeemed';
const isInvalidStatus = ['expired', 'invalid'].includes(status.toLowerCase());
const isExpired = expiresAt ? now.getTime() > expiresAt.getTime() : false;

let reason = '';
let message = '';
let canRedeem = true;

if (!record.id) {
  canRedeem = false;
  reason = 'not_found';
  message = 'Coupon non trovato.';
} else if (!storedToken) {
  canRedeem = false;
  reason = 'missing_redeem_token_field';
  message = 'Configurazione incompleta: nel record coupon manca il campo Redeem Token.';
} else if (!tokenMatches) {
  canRedeem = false;
  reason = 'token_mismatch';
  message = 'Token QR non valido per questo coupon.';
} else if (isRedeemed) {
  canRedeem = false;
  reason = 'already_redeemed';
  message = 'Coupon gia utilizzato' + (field('Redeemed At') ? ' il ' + field('Redeemed At') : '') + '.';
} else if (isInvalidStatus) {
  canRedeem = false;
  reason = 'invalid_status';
  message = 'Coupon non utilizzabile. Stato attuale: ' + status + '.';
} else if (isExpired) {
  canRedeem = false;
  reason = 'expired';
  message = 'Coupon scaduto.';
} else if (!allowOutsidePromoForTest && (!isPromoDay || !isPromoHour)) {
  canRedeem = false;
  reason = 'outside_promo_window';
  message = 'Promo attiva solo dal lunedi al giovedi, 18:30-22:30.';
}

if (canRedeem) {
  reason = 'ok';
  message = 'Coupon valido. Segnato come usato.';
}

return [{ json: {
  ...record,
  recordId: record.id,
  code: request.code,
  token: request.token,
  storedTokenConfigured: storedToken ? 'true' : 'false',
  tokenMatches: tokenMatches ? 'true' : 'false',
  isConfirmRequest: request.isConfirmRequest,
  pinOk: request.pinOk,
  scannedAt: request.scannedAt,
  scannedAtItaly: request.scannedAtItaly,
  redeemedBy: request.redeemedBy,
  canRedeem: canRedeem ? 'true' : 'false',
  reason,
  message,
  status,
  name: field('Name'),
  email: field('Email'),
  phone: field('Phone'),
  couponCode: field('Coupon Code', request.code),
  expiresAt: expiresAtRaw,
  redeemedAt: field('Redeemed At'),
  redeemAttempts,
  redeemAttemptsNext: redeemAttempts + 1,
  checkedWeekday: weekday,
  checkedTime: String(hour).padStart(2, '0') + ':' + String(minute).padStart(2, '0'),
} }];

