parameters.jsCode:
const items = $input.all();
return items.map(item => {
  const row = item.json;
  if (!row || Object.keys(row).length === 0 || row.id === undefined) {
    return { json: {} };
  }
  return {
    json: {
      id: row.id,
      fields: {
        "Status": row.status,
        "Redeem Token": row.redeem_token,
        "Expires At": row.expires_at,
        "Redeem Attempts": row.redeem_attempts,
        "Redeemed At": row.redeemed_at_text,
        "Name": row.name,
        "Email": row.email,
        "Phone": row.phone,
        "Coupon Code": row.coupon_code,
        "Redeem URL": row.redeem_url,
        "QR Image URL": row.qr_image_url,
        "Redemption Mode": row.redemption_mode,
        "Promo Days": row.promo_days,
        "Promo Hours": row.promo_hours
      }
    }
  };
});
